Definition is_rng (b n : expr) (b0 : expr) (L : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S00$b;R+;$n;R+;$b0;R+;$L;R+<!2'\!2'^4#4#2!2'^4#3!1,C#1").
